import type { Bytes } from './bytes.js';
import type { DoubleFloat } from './float.js';
import type { Annotated } from './annotated.js';
import type { JsDictionary } from './jsdictionary.js';
import { Set, KeyedDictionary } from './dictionary.js';
import type { Embeddable, GenericEmbedded } from './embedded.js';
export type Value<T extends Embeddable = GenericEmbedded> = Atom | Compound<T> | T | Annotated<T>;
export type Atom = boolean | DoubleFloat | number | bigint | string | Bytes | symbol;
export type Compound<T extends Embeddable = GenericEmbedded> = (Array<Value<T>> | [Value<T>]) & {
    label: Value<T>;
} | Array<Value<T>> | Set<T> | JsDictionary<Value<T>> | KeyedDictionary<T>;
